INSERT INTO public.cms_pages (slug, title, published, blocks)
VALUES (
  'pricing',
  '{"en":"Pricing","pt-BR":"Preços"}'::jsonb,
  true,
  '[{"type":"heading","level":1,"text":{"en":"Pricing","pt-BR":"Preços"},"align":"center"},{"type":"text","align":"center","text":{"en":"The Leading Sires Registry is an independent global reference, not a marketplace. Listings are presented in a consistent, non commercial format and are not ranked, promoted, or prioritised.","pt-BR":"O Leading Sires Registry é uma referência global independente, não um marketplace. Os anúncios são apresentados em formato consistente e não comercial e não são classificados, promovidos ou priorizados."}},{"type":"heading","level":2,"text":{"en":"Stallion Listings","pt-BR":"Anúncios de Garanhões"},"pricingCard":true},{"type":"text","text":{"en":"Farm/Ranch Registry Account – 79 per year\n\n(USD/EUR/AUD/CAD/NZD – billed in your selected country)\n\n• Unlimited stallion profiles under one farm or ranch\n• Standardised stallion pages with verified registry links\n• Genetics, breeding information, media and service provider links\n• Updates managed annually or as required\n• No advertising, no featured placements, no performance rankings","pt-BR":"Conta de Registro de Fazenda/Haras – 79 por ano\n\n(USD/EUR/AUD/CAD/NZD – cobrado no país selecionado)\n\n• Perfis ilimitados de garanhões sob uma fazenda ou haras\n• Páginas padronizadas de garanhões com links de registro verificados\n• Genética, informações de reprodução, mídia e links de provedores de serviço\n• Atualizações gerenciadas anualmente ou conforme necessário\n• Sem publicidade, sem destaques pagos, sem rankings de performance"}},{"type":"heading","level":2,"text":{"en":"Pedigree-Only & Historical Listings","pt-BR":"Anúncios Apenas de Pedigree e Históricos"}},{"type":"text","text":{"en":"Pedigree and lineage records may be included at no cost where a stallion is:\n\n• deceased\n• no longer standing\n• of historical or breeding significance only\n\nThese records are presented for reference and research purposes and do not imply current availability or commercial activity.","pt-BR":"Registros de pedigree e linhagem podem ser incluídos sem custo quando um garanhão está:\n\n• falecido\n• fora de reprodução\n• apenas de significância histórica ou reprodutiva\n\nEsses registros são apresentados para fins de referência e pesquisa e não implicam disponibilidade atual ou atividade comercial."}},{"type":"heading","level":2,"text":{"en":"International Listings & Currency","pt-BR":"Anúncios Internacionais e Moeda"}},{"type":"text","text":{"en":"The Leading Sires Registry supports listings across:\n\n• Australia\n• New Zealand\n• Canada\n• North & South America\n• Europe","pt-BR":"O Leading Sires Registry suporta anúncios em:\n\n• Austrália\n• Nova Zelândia\n• Canadá\n• América do Norte e do Sul\n• Europa"}},{"type":"heading","level":2,"text":{"en":"Important Notes","pt-BR":"Notas Importantes"}},{"type":"text","text":{"en":"• The Leading Sires Registry is not a stud book, association or marketplace.\n• Listings are factual and reference based.","pt-BR":"• O Leading Sires Registry não é um stud book, associação ou marketplace.\n• Os anúncios são factuais e baseados em referência."}}]'::jsonb
)
